node <<'NODE'
"use strict";
const fs=require("node:fs");
const cp=require("node:child_process");
const root="workspaces/codespace-mcp-srs-design/local-terminals";
const marker=root+"/.gitkeep";
const repo="BestNameYet/Terminals";
function gh(args,input){
  const p=cp.spawnSync("gh",["api",...args],{input,encoding:"utf8",timeout:60000,maxBuffer:4*1024*1024});
  if(p.error||p.status!==0)throw Error("GitHub operation failed: "+(p.stderr||p.error?.message||"unknown").slice(0,500));
  return JSON.parse(p.stdout);
}
if(fs.existsSync(root)){
  if(!fs.statSync(root).isDirectory())throw Error("Target exists but is not a directory");
  console.log(JSON.stringify({status:"ALREADY_EXISTS_VERIFIED",path:root}));
} else {
  const bytes="\n";
  const result=gh(["repos/"+repo+"/contents/"+marker,"--method","PUT","--input","-"],JSON.stringify({message:"Create local-terminals directory for Codespace MCP design",content:Buffer.from(bytes,"utf8").toString("base64")}));
  const read=gh(["repos/"+repo+"/contents/"+marker]);
  if(Buffer.from(read.content.replace(/\s/g,""),"base64").toString("utf8")!==bytes)throw Error("Marker readback mismatch");
  if(result.content?.sha!==read.sha)throw Error("Blob SHA mismatch");
  const listing=gh(["repos/"+repo+"/contents/"+root]);
  if(!Array.isArray(listing)||!listing.some(x=>x.path===marker&&x.type==="file"))throw Error("Directory listing verification failed");
  console.log(JSON.stringify({status:"CREATED_AND_VERIFIED",path:root,marker,commit_sha:result.commit?.sha,blob_sha:read.sha,entries:listing.length}));
}
